// A fresh, started copy of the sample assignment with every step upcoming and no notes, checks or undo.
// Used by tests.
export function createSampleAssignment(id: string): Assignment {
  const copy = structuredClone(sampleAssignment);
  return {
    ...copy,
    id,
    status: "active",
    steps: copy.steps.map((step) => ({ ...step, status: "upcoming", note: "", noteSavedAt: null, noteHidden: false })),
    finalChecks: {},
    lastUndo: null,
    completedAt: null,
    finalReviewedAt: null,
  };
}

// The sample as a PlanSource returns it: just the plan, with no progress fields.
export function createSamplePlan(): PlanDraft {
  const copy = structuredClone(sampleAssignment);
  return {
    title: copy.title,
    course: copy.course,
    summary: copy.summary,
    deadline: copy.deadline,
    requirements: copy.requirements,
    steps: copy.steps.map(({ id, title, intro, whatToDo, doneWhen, completedSummary, estimateMin }) => ({
      id,
      title,
      intro,
      whatToDo,
      doneWhen,
      completedSummary,
      estimateMin,
    })),
  };
}
